function shuffleQuizChoices(question) {
  const options = question.options.map((text,index) => ({text, correct:index === question.right}));
  for (let i = options.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [options[i], options[j]] = [options[j], options[i]];
  }
  return {...question, options:options.map(o => o.text), right:options.findIndex(o => o.correct)};
}

const EMT_NEW_QUESTIONS = Object.entries(EMT_NEW_ITEMS).flatMap(([n, rows]) =>
  rows.map(([level,topic,prompt,correct,...answers], index) => {
    const why = answers.pop();
    // Distribute correct positions for manual tests and search previews.
    const right = (+n + index) % 4;
    answers.splice(right, 0, correct);
    return {id:`fund-${n}-${index}`,n:+n,level,topic,prompt,options:answers,right,why};
  })
);

